<?php require_once __DIR__.'/auth.php'; $title='Homepage Slider'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('sliders'); if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); if(($_POST['action']??'')==='delete'){ $items=array_values(array_filter($items,fn($x)=>(int)($x['id']??0)!==$id));write_data('sliders',$items);redirect('slider.php');}$image=trim($_POST['image']??'');if($u=save_uploaded_image('image_file'))$image=$u;if(!$image)$image='srilanka.jpg';$r=['id'=>$id?:next_id($items),'title'=>trim($_POST['title']??''),'image'=>$image];if($id){foreach($items as &$x)if((int)($x['id']??0)===$id)$x=$r;unset($x);}else$items[]=$r;write_data('sliders',$items);redirect('slider.php');}$edit=null;if(isset($_GET['edit']))foreach($items as $x)if((int)($x['id']??0)===(int)$_GET['edit'])$edit=$x;?>
<div class="row g-4"><div class="col-lg-4"><div class="card shadow-sm p-4"><h5 class="fw-bold"><?= $edit?'Edit':'Add' ?> Slide</h5><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label class="form-label mt-3">Title</label><input name="title" class="form-control" value="<?=e($edit['title']??'')?>" required><label class="form-label mt-3">Image URL / filename</label><input name="image" class="form-control" value="<?=e($edit['image']??'')?>"><label class="form-label mt-3">Upload image</label><input type="file" name="image_file" class="form-control" accept="image/*"><button class="btn btn-success w-100 mt-4">Save Slide</button></form></div></div><div class="col-lg-8"><div class="row g-3"><?php foreach($items as $x): ?><div class="col-md-6"><div class="card shadow-sm overflow-hidden"><img src="<?=e(admin_asset($x['image']))?>" style="height:180px;object-fit:cover"><div class="card-body"><h6 class="fw-bold"><?=e($x['title'])?></h6><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$x['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete slide?')"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></div></div><?php endforeach;?></div></div></div><?php include 'admin-foot.php'; ?>